import{_ as e,o as s,c as a,ai as i}from"./chunks/framework.DQi1ytmF.js";const g=JSON.parse('{"title":"MCP tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai/mcp-tools.md","filePath":"guide/ai/mcp-tools.md"}'),d={name:"guide/ai/mcp-tools.md"};function r(o,t,n,c,h,p){return s(),a("div",null,[...t[0]||(t[0]=[i(`<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/ai/mcp-tools.md for this page in Markdown format</div><h1 id="mcp-tools" tabindex="-1">MCP tools <a class="header-anchor" href="#mcp-tools" aria-label="Permalink to &quot;MCP tools&quot;">​</a></h1><p>CraftTS exposes separate MCP servers for documentation, a running application, local logs, and the static dependency graph. Connect only the server required for the task.</p><h2 id="documentation-mcp-craft-ts-mcp" tabindex="-1">Documentation MCP: <code>@craft-ts/mcp</code> <a class="header-anchor" href="#documentation-mcp-craft-ts-mcp" aria-label="Permalink to &quot;Documentation MCP: \`@craft-ts/mcp\`&quot;">​</a></h2><p>Install it in an application or run it without adding a dependency:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @craft-ts/mcp@beta</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @craft-ts/mcp@beta</span></span></code></pre></div><p>Register it in <code>.mcp.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;craft-ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@craft-ts/mcp@beta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>get_best_practices</code></td><td>Load CraftTS rules and the <code>AGENTS.md</code> snippet</td></tr><tr><td><code>search_documentation</code></td><td>Search Learn, Guide, Reference, Resources, or examples</td></tr><tr><td><code>get_documentation_page</code></td><td>Read one documentation page as Markdown</td></tr><tr><td><code>find_examples</code></td><td>Find tutorial and demo examples for a task</td></tr><tr><td><code>list_skills</code></td><td>List the Agent Skills shipped with the package</td></tr><tr><td><code>get_skill</code></td><td>Load a skill or one of its reference files</td></tr><tr><td><code>get_llms_txt</code></td><td>Get the public <code>llms.txt</code> URLs and bundled page index</td></tr></tbody></table><p>This server is read-only and searches the documentation bundled at publish time. It is the right starting point when an agent needs to understand the CraftTS API or conventions.</p><h2 id="live-page-and-registry-mcp" tabindex="-1">Live page and registry MCP <a class="header-anchor" href="#live-page-and-registry-mcp" aria-label="Permalink to &quot;Live page and registry MCP&quot;">​</a></h2><p><code>@craft-ts/function-registry-mcp</code> connects over stdio to an MCP client and over WebSocket to the running development tab:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> registry:mcp</span></span></code></pre></div><p>The <a href="/craft/guide/ai/dev-page.html">Live page MCP</a> page explains the named-control contract, client selection, and <code>page</code> actions.</p><h3 id="browser-surface" tabindex="-1">Browser surface <a class="header-anchor" href="#browser-surface" aria-label="Permalink to &quot;Browser surface&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>page</code></td><td>Read named controls, then <code>goto</code>, <code>fill</code>, <code>click</code>, or <code>press</code> and return the new state</td></tr><tr><td><code>registry.clients</code></td><td>List connected tabs and their <code>ready</code>, <code>connecting</code>, or <code>reloading</code> state</td></tr></tbody></table><p>If multiple tabs are ready, pass the explicit <code>clientId</code>. Never guess based on which tab connected most recently.</p><h3 id="registry-surface" tabindex="-1">Registry surface <a class="header-anchor" href="#registry-surface" aria-label="Permalink to &quot;Registry surface&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>registry.list</code></td><td>List active registry entries</td></tr><tr><td><code>registry.get</code></td><td>Read one registry entry</td></tr><tr><td><code>registry.call</code></td><td>Invoke an active registry entry</td></tr><tr><td><code>registry.logs</code></td><td>Read registry and bridge events</td></tr><tr><td><code>registry.override</code></td><td>Replace a primitive method at runtime for development</td></tr><tr><td><code>registry.restore</code></td><td>Remove a runtime override</td></tr><tr><td><code>registry.&lt;primitive&gt;.*</code></td><td>Read or mutate <code>query</code>, <code>mutation</code>, <code>asyncProcess</code>, and <code>queryParams</code> values</td></tr></tbody></table><p>The primitive-specific tools are:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>registry.query.get / set / update / patch</span></span>
<span class="line"><span>registry.mutation.get / set / update / patch</span></span>
<span class="line"><span>registry.asyncProcess.get / set / update / patch</span></span>
<span class="line"><span>registry.queryParams.get / set / update / patch</span></span></code></pre></div><p><code>query</code>, <code>mutation</code>, and <code>asyncProcess</code> support an optional <code>id</code> for grouped instances. <code>queryParams</code> does not use grouped instance IDs. Runtime overrides and mutating value tools are development-only operations and should never be connected to an untrusted or production browser.</p><h2 id="logs-mcp-craft-ts-log-mcp" tabindex="-1">Logs MCP: <code>@craft-ts/log-mcp</code> <a class="header-anchor" href="#logs-mcp-craft-ts-log-mcp" aria-label="Permalink to &quot;Logs MCP: \`@craft-ts/log-mcp\`&quot;">​</a></h2><p>The logs server reads JSONL files written by the Craft log server. It does not talk to the browser or ingest logs itself:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs:mcp</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>logs.stats</code></td><td>Summarise levels, host tags, client IDs, files, and time range</td></tr><tr><td><code>logs.search</code></td><td>Filter by text, level, host ancestry, correlation ID, client, or time range</td></tr><tr><td><code>logs.tail</code></td><td>Read the most recent entries</td></tr><tr><td><code>logs.clear</code></td><td>Delete all active and rotated log files</td></tr></tbody></table><p>Use <code>logs.stats</code> before <code>logs.search</code> to understand what is available. The <code>from</code> filter follows Craft host-tag ancestry, and <code>correlationId</code> finds all entries from one correlated flow.</p><p><code>logs.clear</code> is the only destructive tool in this server. Use it only when a clean reproduction is intentional.</p><h2 id="graph-mcp-craft-ts-graph-mcp" tabindex="-1">Graph MCP: <code>@craft-ts/graph-mcp</code> <a class="header-anchor" href="#graph-mcp-craft-ts-graph-mcp" aria-label="Permalink to &quot;Graph MCP: \`@craft-ts/graph-mcp\`&quot;">​</a></h2><p>The graph server answers architecture questions about <strong>your</strong> project from the same static analysis as the <a href="/craft/guide/testing/architecture.html">architecture rules</a>: routes, components, services, primitives and the proven relations between them. It needs no running application. It reads <code>craft-dependency-graph.json</code> when the file exists and otherwise analyses the TypeScript program.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @craft-ts/graph-mcp</span></span></code></pre></div><p>Projects created with <code>craft create</code> already register it. In an existing project, add it to <code>.mcp.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;craft-ts-graph&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;craft-ts-graph-mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>graph.status</code></td><td>Source and build time of the graph, counts per kind, diagnostics</td></tr><tr><td><code>graph.rebuild</code></td><td>Re-analyse the program and overwrite the graph file</td></tr><tr><td><code>graph.search</code></td><td>Find nodes by label or id</td></tr><tr><td><code>graph.node</code></td><td>One node: metrics, relations with their proofs, optionally its source</td></tr><tr><td><code>graph.neighbors</code></td><td>The subgraph around a node, up to three relations away</td></tr><tr><td><code>graph.path</code></td><td>The shortest relation chains between two nodes</td></tr><tr><td><code>graph.impact</code></td><td>Every node whose output may change when this node changes</td></tr><tr><td><code>graph.hotspots</code></td><td>God nodes and hotspots, optionally weighted by git churn</td></tr><tr><td><code>graph.report</code></td><td>The <a href="/craft/guide/testing/graph-insights.html#report">graph report</a> as JSON</td></tr><tr><td><code>graph.violations</code></td><td>The rules <code>assertArchitecture</code> enforces, by name, with their messages</td></tr></tbody></table><p>Every answer carries <code>stale</code>: <code>true</code> when a source file changed after the graph was built, <code>unknown</code> when no tsconfig is available to check. An agent calls <code>graph.rebuild</code> before answering about recent code.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th></tr></thead><tbody><tr><td><code>CRAFT_GRAPH_ROOT</code></td><td>The current directory</td></tr><tr><td><code>CRAFT_GRAPH_TSCONFIG</code></td><td>First of <code>tsconfig.graph.json</code>, <code>tsconfig.app.json</code>, <code>tsconfig.json</code></td></tr><tr><td><code>CRAFT_GRAPH_FILE</code></td><td><code>craft-dependency-graph.json</code></td></tr><tr><td><code>CRAFT_GRAPH_COVERAGE</code></td><td>Unset; a <code>coverage-final.json</code> to attach coverage per node and route</td></tr><tr><td><code>CRAFT_GRAPH_DOCS</code></td><td>Unset; comma-separated Markdown globs linked to the nodes they cite</td></tr><tr><td><code>CRAFT_GRAPH_READONLY</code></td><td>Unset; <code>1</code> removes <code>graph.rebuild</code>, for CI or shared environments</td></tr></tbody></table><p>All tools except <code>graph.rebuild</code> are read-only, and <code>graph.rebuild</code> only writes the graph file.</p><h3 id="projects-created-earlier" tabindex="-1">Projects created earlier <a class="header-anchor" href="#projects-created-earlier" aria-label="Permalink to &quot;Projects created earlier&quot;">​</a></h3><p><code>craft agents sync</code> adds today&#39;s agent wiring to a project generated by an older CraftTS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # list what would change</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> craft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agents</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> graph</span></span></code></pre></div><p>It adds the skills and hooks of the agents the project already uses (detected from <code>.agents/</code>, <code>.claude/</code>, <code>.cursor/</code> and <code>.gemini/</code>, or named with <code>--agents</code>), registers the graph server in <code>.mcp.json</code> without touching the servers already there, adds the <code>graph</code> and <code>graph:mcp</code> scripts and the dependency, and ignores the graph output. It never writes application code, and a second run reports that nothing changed.</p><p>Do not use <code>craft create --force</code> for this: it rewrites every generated file, <code>src/</code> included.</p><h2 id="which-server-should-an-agent-use" tabindex="-1">Which server should an agent use? <a class="header-anchor" href="#which-server-should-an-agent-use" aria-label="Permalink to &quot;Which server should an agent use?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Server</th></tr></thead><tbody><tr><td>“How should I write this Craft code?”</td><td>Documentation MCP</td></tr><tr><td>“What is visible on the running page?”</td><td>Function registry MCP → <code>page</code></td></tr><tr><td>“What value does this query have?”</td><td>Function registry MCP → <code>registry.query.get</code></td></tr><tr><td>“What happened during this flow?”</td><td>Logs MCP → <code>logs.stats</code>, then <code>logs.search</code></td></tr><tr><td>“What does this service depend on?”</td><td>Graph MCP → <code>graph.search</code>, then <code>graph.node</code></td></tr><tr><td>“What can this change break?”</td><td>Graph MCP → <code>graph.impact</code></td></tr><tr><td>“What context should I send to an AI?”</td><td><code>provideSendContextToAi</code>, then copy or send the payload</td></tr></tbody></table>`,44)])])}const k=e(d,[["render",r]]);export{g as __pageData,k as default};
